templates.react:
export function Digest({
  title = '{{title}}',
  period = '{{period}}',
  itemCount = {{itemCount}},
  highlight = '{{highlight}}',
  accent = '{{accent}}',
  expanded = {{expanded}},
}) {
  return (
    <details open={expanded} style={{ maxWidth: 420, padding: '14px 16px', background: '#FAF7F2', color: '#241430', borderRadius: 10, borderLeft: `4px solid ${accent}`, boxShadow: '0 6px 18px rgba(36,20,48,.12)', fontFamily: 'system-ui, sans-serif', fontSize: 14 }}>
      <summary style={{ cursor: 'pointer', fontWeight: 600, listStyle: 'none' }}>
        {title} · <span style={{ textTransform: 'capitalize' }}>{period}</span> digest — {itemCount} updates
      </summary>
      <ul style={{ margin: '10px 0 0', paddingLeft: 20, fontSize: 13, color: '#241430cc' }}>
        <li style={{ marginBottom: 4 }}><strong>{highlight}</strong> shipped the new roadmap view</li>
        <li style={{ marginBottom: 4 }}>3 comments resolved on the design spec</li>
        <li style={{ marginBottom: 4 }}>Weekly usage rose 12% across active teams</li>
      </ul>
    </details>
  );
}
